on conflict (registry_id, card_id) do update
set set_code = excluded.set_code,
    name = excluded.name,
    element = excluded.element,
    card_family = excluded.card_family,
    card_schema = excluded.card_schema,
    effect_schema = excluded.effect_schema,
    definition = excluded.definition,
    updated_at = now();

do $tcg$
declare
  v_count integer;
  v_bad integer;
  v_digest text;
  v_authority boolean;
begin
  select card_count, registry_sha256, is_runtime_authority
    into v_count, v_digest, v_authority
  from public.tcg_registry_versions
  where registry_id = 'SB1-set-one-v0.2';

  if v_count <> 193 then
    raise exception 'tcg_v0_2_shadow_registry_metadata_count_mismatch: expected 193, got %', v_count;
  end if;
  if v_digest <> 'b1bc874a6d3707f5c93cd4067994a12111416da636cb15048d10e109829b1c00' then
    raise exception 'tcg_v0_2_shadow_registry_digest_mismatch';
  end if;
  if coalesce(v_authority, false) then
    raise exception 'tcg_v0_2_shadow_registry_must_not_be_runtime_authority';
  end if;

  select count(*)::int into v_count
  from public.tcg_card_definition_versions
  where registry_id = 'SB1-set-one-v0.2';
  if v_count <> 193 then
    raise exception 'tcg_v0_2_shadow_registry_row_count_mismatch: expected 193, got %', v_count;
  end if;

  select count(*)::int into v_bad
  from public.tcg_card_definition_versions
  where registry_id = 'SB1-set-one-v0.2'
    and (
      set_code <> 'SB1'
      or card_schema <> 'sb-tcg-card-v0.2'
      or effect_schema <> 'sb-tcg-effects-v0.2'
      or definition ->> 'id' <> card_id
      or definition ->> 'name' <> name
      or definition ->> 'card_family' <> card_family
      or definition ->> 'schema' <> card_schema
      or definition ->> 'effect_schema' <> effect_schema
    );
  if v_bad <> 0 then
    raise exception 'tcg_v0_2_shadow_registry_structured_row_mismatch: % invalid rows', v_bad;
  end if;
end
$tcg$;
